import{_ as i,C as s,o as c,c as u,ag as r,E as n,w as t,a}from"./chunks/framework.BSwSpTvy.js";const k=JSON.parse('{"title":"☁️ Azure Anthropic & Token Caching","description":"","frontmatter":{},"headers":[],"relativePath":"features/azure-anthropic.md","filePath":"features/azure-anthropic.md"}'),l={name:"features/azure-anthropic.md"};function h(d,e,p,g,m,f){const o=s("ZedChat");return c(),u("div",null,[e[4]||(e[4]=r('<h1 id="☁️-azure-anthropic-token-caching" tabindex="-1">☁️ Azure Anthropic &amp; Token Caching <a class="header-anchor" href="#☁️-azure-anthropic-token-caching" aria-label="Permalink to &quot;☁️ Azure Anthropic &amp; Token Caching&quot;">​</a></h1><p>This fork provides native integration for Azure OpenAI/Foundry Anthropic deployments and real-time visualization of Anthropic&#39;s <strong>Prompt Caching</strong> (Beta).</p><h2 id="native-azure-support" tabindex="-1">Native Azure Support <a class="header-anchor" href="#native-azure-support" aria-label="Permalink to &quot;Native Azure Support&quot;">​</a></h2><p>Standard Anthropic providers in Zed often fail with <code>404 DeploymentNotFound</code> because they passdated version strings (e.g., <code>claude-3-5-sonnet-20241022</code>) that Azure strictly rejects.</p><p>We modified <code>crates/anthropic/src/anthropic.rs</code> to intercept model resolution. When a custom <code>api_url</code> is detected, Zed automatically forwards the exact <code>serde_name</code> string you provided in settings, ensuring your Azure deployment name is matched perfectly.</p><h2 id="prompt-caching-ui" tabindex="-1">Prompt Caching UI <a class="header-anchor" href="#prompt-caching-ui" aria-label="Permalink to &quot;Prompt Caching UI&quot;">​</a></h2><p>For massive context windows (200k+ tokens), sending the entire codebase on every turn is slow and expensive. Anthropic&#39;s <strong>Prompt Caching</strong> stores prefixes on their servers for roughly 5 minutes.</p><p>In this build, the <code>show_turn_stats</code> visualization is <strong>enabled by default</strong>.</p><h2 id="visual-walkthrough-caching-roi" tabindex="-1">Visual Walkthrough: Caching ROI <a class="header-anchor" href="#visual-walkthrough-caching-roi" aria-label="Permalink to &quot;Visual Walkthrough: Caching ROI&quot;">​</a></h2>',9)),n(o,null,{user:t(()=>[...e[0]||(e[0]=[a(" (First Turn: Sends 50 files) Summarize the overall architecture. ",-1)])]),assistant:t(()=>[...e[1]||(e[1]=[a(" >> 0 tokens cached >> 45,000 tokens input Generating summary... ",-1)])]),_:1}),n(o,null,{user:t(()=>[...e[2]||(e[2]=[a(" (Second Turn: Asks follow-up) Now find the specific logic for the auth handler. ",-1)])]),assistant:t(()=>[...e[3]||(e[3]=[a(" >> 45,200 tokens cached (ROI! ⚡️) >> 150 tokens input Locating auth handler... ",-1)])]),_:1}),e[5]||(e[5]=r('<h2 id="workflow-impact" tabindex="-1">Workflow Impact <a class="header-anchor" href="#workflow-impact" aria-label="Permalink to &quot;Workflow Impact&quot;">​</a></h2><ul><li><strong>Enterprise Compliance</strong>: Securely use LLMs within Azure&#39;s managed infrastructure and VPCs.</li><li><strong>Zero-Wait Context</strong>: Massive projects that usually take 10s to process now respond in &lt;1s due to prefix caching.</li><li><strong>Dramatic Cost Savings</strong>: Pay up to 90% less for the &quot;static&quot; project context that doesn&#39;t change between turns.</li><li><strong>Perfect Routing</strong>: Eliminates the &quot;404 Model Not Found&quot; errors by matching exact Azure deployment names.</li></ul>',2))])}const A=i(l,[["render",h]]);export{k as __pageData,A as default};
